sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var handoffs = [];

    var gr = new GlideRecordSecure('x_2130921_caresy_0_patient_handoff');
    gr.orderByDesc('handoff_date');
    gr.query();

    while (gr.next()) {

        handoffs.push({
            sys_id: gr.getUniqueValue(),

            handoff_number: gr.getValue('number'),

            patient_sys_id: gr.getValue('patient'),
            patient: gr.getDisplayValue('patient'),

            admission_sys_id: gr.getValue('admission'),
            admission: gr.getDisplayValue('admission'),

            handoff_type: gr.getDisplayValue('handoff_type'),

            from_department_sys_id: gr.getValue('from_department'),
            from_department: gr.getDisplayValue('from_department'),

            to_department_sys_id: gr.getValue('to_department'),
            to_department: gr.getDisplayValue('to_department'),

            from_ward_sys_id: gr.getValue('from_ward'),
            from_ward: gr.getDisplayValue('from_ward'),

            to_ward_sys_id: gr.getValue('to_ward'),
            to_ward: gr.getDisplayValue('to_ward'),

            from_bed_sys_id: gr.getValue('from_bed'),
            from_bed: gr.getDisplayValue('from_bed'),

            to_bed_sys_id: gr.getValue('to_bed'),
            to_bed: gr.getDisplayValue('to_bed'),

            handoff_date: gr.getValue('handoff_date'),

            handed_over_by_sys_id: gr.getValue('handed_over_by'),
            handed_over_by: gr.getDisplayValue('handed_over_by'),

            received_by_sys_id: gr.getValue('received_by'),
            received_by: gr.getDisplayValue('received_by'),

            handoff_status: gr.getDisplayValue('handoff_status'),

            handoff_notes: gr.getValue('handoff_notes'),

            active: gr.getValue('active') == '1'
        });
    }

    response.setStatus(200);

    response.setBody({
        success: true,
        count: handoffs.length,
        patient_handoffs: handoffs
    });

})(request, response);
